-- Application role never owns tables and never has BYPASSRLS.
CREATE SCHEMA IF NOT EXISTS app;
CREATE FUNCTION app.user_id() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'') $$;
CREATE FUNCTION app.org_member(oid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM organization_memberships m JOIN profiles p ON p.id=m.profile_id JOIN organizations o ON o.id=m.organization_id WHERE m.organization_id=oid AND m.profile_id=app.user_id() AND p.status='active' AND o.status='active') $$;
CREATE FUNCTION app.org_admin(oid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM organization_memberships m JOIN profiles p ON p.id=m.profile_id JOIN organizations o ON o.id=m.organization_id WHERE m.organization_id=oid AND m.profile_id=app.user_id() AND m.role IN ('OWNER','ADMIN') AND p.status='active' AND o.status='active') $$;
CREATE FUNCTION app.has_restaurant(rid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM restaurants r JOIN organizations o ON o.id=r.organization_id WHERE r.id=rid AND o.status='active' AND ((current_setting('app.public',true)='true' AND current_setting('app.restaurant_id',true)=rid) OR EXISTS(SELECT 1 FROM memberships m JOIN profiles p ON p.id=m.profile_id WHERE m.restaurant_id=rid AND m.profile_id=app.user_id() AND p.status='active') OR app.org_admin(r.organization_id) OR EXISTS(SELECT 1 FROM support_grants g JOIN platform_admins a ON a.profile_id=g.profile_id JOIN profiles p ON p.id=a.profile_id WHERE g.profile_id=app.user_id() AND p.status='active' AND g.restaurant_id=rid AND g.expires_at>now() AND g.revoked_at IS NULL))) $$;
CREATE FUNCTION app.in_restaurant(rid text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT current_setting('app.restaurant_id',true)=rid AND app.has_restaurant(rid) $$;
CREATE FUNCTION app.shared_profile(pid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships m WHERE m.profile_id=pid AND app.in_restaurant(m.restaurant_id)) $$;
CREATE FUNCTION app.ensure_profile(pid text,pname text,pemail text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF pid IS DISTINCT FROM app.user_id() THEN RAISE EXCEPTION 'Identity mismatch'; END IF;
 INSERT INTO profiles(id,name,role,email) VALUES(pid,pname,'WAITER',pemail) ON CONFLICT(id) DO UPDATE SET name=excluded.name,email=excluded.email;
END $$;
CREATE FUNCTION app.bootstrap_organization(oid text,oname text,rid text,rname text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=app.user_id() AND status='active') THEN RAISE EXCEPTION 'Connexion requise'; END IF;
 IF (SELECT count(*) FROM organization_memberships WHERE profile_id=app.user_id() AND role='OWNER')>=5 THEN RAISE EXCEPTION 'Limite organisations'; END IF;
 INSERT INTO organizations(id,name) VALUES(oid,oname);
 INSERT INTO organization_placements(organization_id) VALUES(oid);
 INSERT INTO organization_memberships VALUES(oid,app.user_id(),'OWNER');
 INSERT INTO restaurants(id,name,organization_id) VALUES(rid,rname,oid);
 INSERT INTO memberships VALUES(app.user_id(),rid,'OWNER');
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM PUBLIC;
