CREATE FUNCTION app.row_restaurant(tab text,rid text) RETURNS text LANGUAGE plpgsql STABLE SET search_path=public,pg_temp AS $$ DECLARE result text; BEGIN CASE tab
WHEN 'audit_logs' THEN EXECUTE 'SELECT restaurant_id FROM audit_logs WHERE id=$1' INTO result USING rid;
WHEN 'customer_access_tokens' THEN EXECUTE 'SELECT restaurant_id FROM customer_access_tokens t JOIN customers p ON p.id=t.customer_id WHERE t.id=$1' INTO result USING rid;
WHEN 'customer_email_outbox' THEN EXECUTE 'SELECT restaurant_id FROM customer_email_outbox t JOIN customers p ON p.id=t.customer_id WHERE t.id=$1' INTO result USING rid;
WHEN 'customer_password_resets' THEN EXECUTE 'SELECT restaurant_id FROM customer_password_resets t JOIN customers p ON p.id=t.customer_id WHERE t.id=$1' INTO result USING rid;
WHEN 'customer_sessions' THEN EXECUTE 'SELECT restaurant_id FROM customer_sessions t JOIN customers p ON p.id=t.customer_id WHERE t.id=$1' INTO result USING rid;
WHEN 'customers' THEN EXECUTE 'SELECT restaurant_id FROM customers WHERE id=$1' INTO result USING rid;
WHEN 'dining_tables' THEN EXECUTE 'SELECT restaurant_id FROM dining_tables WHERE id=$1' INTO result USING rid;
WHEN 'expenses' THEN EXECUTE 'SELECT restaurant_id FROM expenses WHERE id=$1' INTO result USING rid;
WHEN 'ingredients' THEN EXECUTE 'SELECT restaurant_id FROM ingredients WHERE id=$1' INTO result USING rid;
WHEN 'integration_connections' THEN EXECUTE 'SELECT restaurant_id FROM integration_connections WHERE id=$1' INTO result USING rid;
WHEN 'inventory_lines' THEN EXECUTE 'SELECT restaurant_id FROM inventory_lines t JOIN inventory_sessions p ON p.id=t.session_id WHERE t.id=$1' INTO result USING rid;
WHEN 'inventory_sessions' THEN EXECUTE 'SELECT restaurant_id FROM inventory_sessions WHERE id=$1' INTO result USING rid;
WHEN 'loyalty_rewards' THEN EXECUTE 'SELECT restaurant_id FROM loyalty_rewards WHERE id=$1' INTO result USING rid;
WHEN 'loyalty_transactions' THEN EXECUTE 'SELECT restaurant_id FROM loyalty_transactions t JOIN customers p ON p.id=t.customer_id WHERE t.id=$1' INTO result USING rid;
WHEN 'menu_items' THEN EXECUTE 'SELECT restaurant_id FROM menu_items WHERE id=$1' INTO result USING rid;
WHEN 'notification_reads' THEN EXECUTE 'SELECT restaurant_id FROM notification_reads t JOIN notifications p ON p.id=t.notification_id WHERE t.id=$1' INTO result USING rid;
WHEN 'notifications' THEN EXECUTE 'SELECT restaurant_id FROM notifications WHERE id=$1' INTO result USING rid;
WHEN 'offline_allocations' THEN EXECUTE 'SELECT (SELECT restaurant_id FROM offline_devices WHERE id=p.device_id) FROM offline_allocations t JOIN offline_quotas p ON p.id=t.quota_id WHERE t.id=$1' INTO result USING rid;
WHEN 'offline_devices' THEN EXECUTE 'SELECT restaurant_id FROM offline_devices WHERE id=$1' INTO result USING rid;
WHEN 'offline_operations' THEN EXECUTE 'SELECT restaurant_id FROM offline_operations t JOIN offline_devices p ON p.id=t.device_id WHERE t.id=$1' INTO result USING rid;
WHEN 'offline_quotas' THEN EXECUTE 'SELECT restaurant_id FROM offline_quotas t JOIN offline_devices p ON p.id=t.device_id WHERE t.id=$1' INTO result USING rid;
WHEN 'option_recipes' THEN EXECUTE 'SELECT restaurant_id FROM option_recipes t JOIN menu_items p ON p.id=t.menu_id WHERE t.id=$1' INTO result USING rid;
WHEN 'order_items' THEN EXECUTE 'SELECT restaurant_id FROM order_items t JOIN orders p ON p.id=t.order_id WHERE t.id=$1' INTO result USING rid;
WHEN 'orders' THEN EXECUTE 'SELECT restaurant_id FROM orders WHERE id=$1' INTO result USING rid;
WHEN 'outbox_jobs' THEN EXECUTE 'SELECT restaurant_id FROM outbox_jobs WHERE id=$1' INTO result USING rid;
WHEN 'product_reviews' THEN EXECUTE 'SELECT restaurant_id FROM product_reviews WHERE id=$1' INTO result USING rid;
WHEN 'promo_codes' THEN EXECUTE 'SELECT restaurant_id FROM promo_codes WHERE id=$1' INTO result USING rid;
WHEN 'promo_redemptions' THEN EXECUTE 'SELECT restaurant_id FROM promo_redemptions t JOIN orders p ON p.id=t.order_id WHERE t.id=$1' INTO result USING rid;
WHEN 'purchase_document_lines' THEN EXECUTE 'SELECT restaurant_id FROM purchase_document_lines t JOIN purchase_documents p ON p.id=t.document_id WHERE t.id=$1' INTO result USING rid;
WHEN 'purchase_documents' THEN EXECUTE 'SELECT restaurant_id FROM purchase_documents WHERE id=$1' INTO result USING rid;
WHEN 'purchase_orders' THEN EXECUTE 'SELECT restaurant_id FROM purchase_orders WHERE id=$1' INTO result USING rid;
WHEN 'receipts' THEN EXECUTE 'SELECT restaurant_id FROM receipts t JOIN purchase_orders p ON p.id=t.purchase_id WHERE t.id=$1' INTO result USING rid;
WHEN 'recipe_ingredients' THEN EXECUTE 'SELECT restaurant_id FROM recipe_ingredients t JOIN menu_items p ON p.id=t.menu_id WHERE t.id=$1' INTO result USING rid;
WHEN 'reservations' THEN EXECUTE 'SELECT restaurant_id FROM reservations WHERE id=$1' INTO result USING rid;
WHEN 'restaurant_domains' THEN EXECUTE 'SELECT restaurant_id FROM restaurant_domains WHERE id=$1' INTO result USING rid;
WHEN 'restaurant_events' THEN EXECUTE 'SELECT restaurant_id FROM restaurant_events WHERE id=$1' INTO result USING rid;
WHEN 'restaurants' THEN EXECUTE 'SELECT id FROM restaurants WHERE id=$1' INTO result USING rid;
WHEN 'shifts' THEN EXECUTE 'SELECT restaurant_id FROM shifts WHERE id=$1' INTO result USING rid;
WHEN 'shop_orders' THEN EXECUTE 'SELECT restaurant_id FROM shop_orders t JOIN orders p ON p.id=t.order_id WHERE t.id=$1' INTO result USING rid;
WHEN 'site_assets' THEN EXECUTE 'SELECT restaurant_id FROM site_assets WHERE id=$1' INTO result USING rid;
WHEN 'site_publications' THEN EXECUTE 'SELECT restaurant_id FROM site_publications WHERE id=$1' INTO result USING rid;
WHEN 'stock_lots' THEN EXECUTE 'SELECT restaurant_id FROM stock_lots t JOIN ingredients p ON p.id=t.ingredient_id WHERE t.id=$1' INTO result USING rid;
WHEN 'stock_movements' THEN EXECUTE 'SELECT restaurant_id FROM stock_movements WHERE id=$1' INTO result USING rid;
WHEN 'stock_reservations' THEN EXECUTE 'SELECT (SELECT restaurant_id FROM orders WHERE id=p.order_id) FROM stock_reservations t JOIN order_items p ON p.id=t.item_id WHERE t.id=$1' INTO result USING rid;
WHEN 'suppliers' THEN EXECUTE 'SELECT restaurant_id FROM suppliers WHERE id=$1' INTO result USING rid;
WHEN 'table_sessions' THEN EXECUTE 'SELECT restaurant_id FROM table_sessions t JOIN dining_tables p ON p.id=t.table_id WHERE t.id=$1' INTO result USING rid;
WHEN 'time_entries' THEN EXECUTE 'SELECT restaurant_id FROM time_entries WHERE id=$1' INTO result USING rid;
ELSE RAISE EXCEPTION 'Unknown tenant table'; END CASE; RETURN result; END $$;
CREATE FUNCTION app.guard_links() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE doc jsonb:=to_jsonb(NEW); scope_id text:=doc->>'restaurant_id'; other text; i integer; BEGIN
 FOR i IN 0..TG_NARGS/2-1 LOOP
 IF doc->>TG_ARGV[i*2] IS NOT NULL THEN
 other:=app.row_restaurant(TG_ARGV[i*2+1],doc->>TG_ARGV[i*2]);
 IF other IS NULL THEN RAISE EXCEPTION 'Reference hors etablissement'; END IF;
 IF scope_id IS NULL THEN scope_id:=other; ELSIF scope_id<>other THEN RAISE EXCEPTION 'Reference hors etablissement'; END IF;
 END IF;
 END LOOP; RETURN NEW; END $$;
