CREATE FUNCTION app.consume_rate_limit(key text,max_hits integer,window_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE n integer; BEGIN
 INSERT INTO rate_limits(bucket,hits,expires_at) VALUES(key,1,now()+make_interval(secs=>window_seconds)) ON CONFLICT(bucket) DO UPDATE SET hits=CASE WHEN rate_limits.expires_at<now() THEN 1 ELSE rate_limits.hits+1 END,expires_at=CASE WHEN rate_limits.expires_at<now() THEN excluded.expires_at ELSE rate_limits.expires_at END RETURNING hits INTO n; RETURN n<=max_hits; END $$;
CREATE FUNCTION app.resolve_domain(host text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT d.restaurant_id FROM restaurant_domains d JOIN restaurants r ON r.id=d.restaurant_id JOIN organizations o ON o.id=r.organization_id WHERE d.hostname=lower(host) AND d.verified_at IS NOT NULL AND o.status='active' $$;
CREATE FUNCTION app.is_platform_admin(pid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM platform_admins WHERE profile_id=pid) $$;
CREATE FUNCTION app.accept_invitation(hashed text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE inv invitations%ROWTYPE; email text; item text; BEGIN
 SELECT p.email INTO email FROM profiles p WHERE p.id=app.user_id() AND p.status='active';
 SELECT * INTO inv FROM invitations WHERE token_hash=hashed AND expires_at>now() AND accepted_at IS NULL FOR UPDATE;
 IF inv.id IS NULL OR email IS NULL OR lower(email)<>inv.email THEN RAISE EXCEPTION 'Invitation non autorisée'; END IF;
 IF NOT EXISTS(SELECT 1 FROM organizations WHERE id=inv.organization_id AND status='active') THEN RAISE EXCEPTION 'Organisation suspendue'; END IF;
 INSERT INTO organization_memberships VALUES(inv.organization_id,app.user_id(),'MEMBER') ON CONFLICT DO NOTHING;
 FOR item IN SELECT jsonb_array_elements_text(inv.roles) LOOP
 IF item NOT IN ('OWNER','MANAGER','WAITER','CHEF','BARTENDER','STOCK_MANAGER','PURCHASING','ACCOUNTANT') THEN RAISE EXCEPTION 'Role invalide'; END IF;
 INSERT INTO memberships VALUES(app.user_id(),inv.restaurant_id,item) ON CONFLICT DO NOTHING;
 END LOOP;
 UPDATE invitations SET accepted_at=now() WHERE id=inv.id;
 INSERT INTO audit_logs(id,restaurant_id,actor,action,object_id) VALUES(gen_random_uuid()::text,inv.restaurant_id,app.user_id(),'Invitation acceptée',inv.id);
 END $$;
CREATE FUNCTION app.setup_restaurant() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 INSERT INTO shop_settings(restaurant_id,config) VALUES(NEW.id,'{"open":false,"prepMinutes":20,"interval":15,"capacity":10,"hours":[],"categories":["Entrées","Plats","Desserts","Boissons"],"address":"","phone":"","logo":""}');
 INSERT INTO site_documents(restaurant_id) VALUES(NEW.id);
 INSERT INTO outbox_jobs(id,restaurant_id,kind,payload,dedupe_key) VALUES(gen_random_uuid()::text,NEW.id,'security_scan','{}'::jsonb,'initial');
 RETURN NEW; END $$;
CREATE TRIGGER restaurant_setup AFTER INSERT ON restaurants FOR EACH ROW EXECUTE FUNCTION app.setup_restaurant();
CREATE FUNCTION app.emit_event() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE doc jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; BEGIN
 INSERT INTO restaurant_events(restaurant_id,event_type,resource_id) VALUES(doc->>'restaurant_id',TG_TABLE_NAME||'.'||lower(TG_OP),doc->>'id');
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER orders_event AFTER INSERT OR UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION app.emit_event();
CREATE TRIGGER menu_event AFTER INSERT OR UPDATE ON menu_items FOR EACH ROW EXECUTE FUNCTION app.emit_event();
CREATE TRIGGER notice_event AFTER INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION app.emit_event();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM PUBLIC;
